-- ============================================================================
--  Vendas de PDV do dia 2026-09-15 (origem: pantanal27092026) -- id gerado AUTOMATICAMENTE no destino
--  Nao usa o id da origem: cada linha ganha um id novo (auto_increment).
--  Se o id ja existir no destino, nao importa -- o banco cria outro.
--  As FKs (itens->venda, estoque->item, etc.) sao religadas via mapa temporario.
--
--  COMO USAR:
--   1) Selecione o banco de destino (descomente e ajuste):
-- USE `seu_banco_de_destino`;
--   2) Rode o script inteiro de uma vez.
--   3) Confira as contagens (95/139/96/139/139) e entao: COMMIT;  (ou ROLLBACK;)
-- ============================================================================
SET NAMES utf8mb4;
SET SESSION sql_mode='';
START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS _stg_v,_stg_i,_stg_c,_stg_m,_stg_p,_stg_v2,_stg_i2,_stg_m2,_map_v,_map_i,_map_e;

-- staging venda_caixas : 95 registros (id original preservado só no staging)
CREATE TEMPORARY TABLE _stg_v LIKE `venda_caixas`;

-- staging item_venda_caixas : 139 registros (id original preservado só no staging)
CREATE TEMPORARY TABLE _stg_i LIKE `item_venda_caixas`;

-- staging conta_recebers : 96 registros (id original preservado só no staging)
CREATE TEMPORARY TABLE _stg_c LIKE `conta_recebers`;

-- staging estoque_movs : 139 registros (id original preservado só no staging)
CREATE TEMPORARY TABLE _stg_m LIKE `estoque_movs`;

-- staging estoquemovpdvs : 139 registros (id original preservado só no staging)
CREATE TEMPORARY TABLE _stg_p LIKE `estoquemovpdvs`;

-- ---- inserção no destino (id automático) + montagem dos mapas ----
-- venda_caixas
SELECT s.`cliente_id`, s.`usuario_id`, s.`natureza_id`, s.`data_registro`, s.`valor_total`, s.`dinheiro_recebido`, s.`troco`, s.`desconto`, s.`acrescimo`, s.`forma_pagamento`, s.`tipo_pagamento`, s.`estado`, s.`NFcNumero`, s.`chave`, s.`path_xml`, s.`nome`, s.`cpf`, s.`observacao`, s.`pedido_delivery_id`, s.`tipo_pagamento_1`, s.`valor_pagamento_1`, s.`tipo_pagamento_2`, s.`valor_pagamento_2`, s.`tipo_pagamento_3`, s.`valor_pagamento_3`, s.`bandeira_cartao`, s.`cnpj_cartao`, s.`cAut_cartao`, s.`descricao_pag_outros`, s.`created_at`, s.`updated_at`, s.`txcartao`, s.`txantcartao`, s.`custo_total`, s.`imposto_total`, s.`bandeira_cartao_2`, s.`bandeira_cartao_1`, s.`bandeira_cartao_3`, s.`ativo`, s.`motivo_cancelamento`, s.`data_cancelamento`, s.`intencao_venda_id` FROM _stg_v s ORDER BY s.`id`;
SET @first := LAST_INSERT_ID();
CREATE TEMPORARY TABLE _stg_v2 LIKE `venda_caixas`;
CREATE TEMPORARY TABLE _map_v (o INT PRIMARY KEY, n INT);

-- item_venda_caixas
SELECT j_venda_caixa_id.n, s.`produto_id`, s.`item_pedido_id`, s.`quantidade`, s.`valor`, s.`observacao`, s.`created_at`, s.`updated_at`, s.`custo_total` FROM _stg_i s LEFT JOIN _map_v j_venda_caixa_id ON j_venda_caixa_id.o = s.`venda_caixa_id` ORDER BY s.`id`;
SET @first := LAST_INSERT_ID();
CREATE TEMPORARY TABLE _stg_i2 LIKE `item_venda_caixas`;
CREATE TEMPORARY TABLE _map_i (o INT PRIMARY KEY, n INT);

-- conta_recebers
SELECT s.`venda_id`, s.`usuario_id`, s.`categoria_id`, s.`referencia`, s.`valor_integral`, s.`valor_recebido`, s.`date_register`, s.`data_vencimento`, s.`data_recebimento`, s.`status`, s.`created_at`, s.`updated_at`, s.`forma_recebimento`, j_venda_caixa_id.n, s.`ativo` FROM _stg_c s LEFT JOIN _map_v j_venda_caixa_id ON j_venda_caixa_id.o = s.`venda_caixa_id` ORDER BY s.`id`;

-- estoque_movs
SELECT s.`produto_id`, s.`tipomov`, s.`origem`, s.`descricao`, s.`quantidade`, s.`valor`, s.`usuario_id`, s.`created_at`, s.`updated_at` FROM _stg_m s ORDER BY s.`id`;
SET @first := LAST_INSERT_ID();
CREATE TEMPORARY TABLE _stg_m2 LIKE `estoque_movs`;
CREATE TEMPORARY TABLE _map_e (o INT PRIMARY KEY, n INT);

-- estoquemovpdvs
SELECT j_estoquemov_id.n, j_estoquepdv_id.n, s.`updated_at`, s.`created_at` FROM _stg_p s LEFT JOIN _map_e j_estoquemov_id ON j_estoquemov_id.o = s.`estoquemov_id` LEFT JOIN _map_i j_estoquepdv_id ON j_estoquepdv_id.o = s.`estoquepdv_id` ORDER BY s.`id`;

-- ---- conferência (deve dar 95 / 139 / 96 / 139 / 139) ----
SELECT (SELECT COUNT(*) FROM _map_v) AS venda_caixas,
       (SELECT COUNT(*) FROM _map_i) AS itens,
       (SELECT COUNT(*) FROM _stg_c) AS contas,
       (SELECT COUNT(*) FROM _map_e) AS estoque_movs,
       (SELECT COUNT(*) FROM _stg_p) AS estoquemovpdvs;

-- Se bater, confirme:
COMMIT;
-- Se algo errado: ROLLBACK;
